function memoizeByKey(fn, keyOf) {
  const cache = new Map();
  return function (...args) {
    const key = keyOf.apply(this, args);
    if (cache.has(key)) return cache.get(key);
    const value = fn.apply(this, args);
    cache.set(key, value);
    return value;
  };
}

const taxableTotal = memoizeByKey(
  (subtotal, rate) => {
    console.log("computing total");
    return subtotal * (1 + rate);
  },
  (subtotal, rate) => `${subtotal}:${rate}`,
);

console.log(taxableTotal(100, 0.1)); // computes
console.log(taxableTotal(100, 0.1)); // uses the cached value

